// compound surfaces a reasoning channel; the model sometimes "performs"
// tool calls there and never repeats them in content. Salvage those, but
// only once per turn — it re-emits the same calls every round.
const key = (c: { tool: string; args: Record<string, unknown> }) =>
  c.tool + JSON.stringify(c.args);
const contentCalls = parseToolCalls(res.content);
const reasoningCalls = res.reasoning ? parseToolCalls(res.reasoning) : [];
const contentKeys = new Set(contentCalls.map(key));
const novelReasoningCalls = reasoningCalls.filter(
  (c) => !contentKeys.has(key(c)) && !turnExecuted.has(key(c)),
);
const calls = [...contentCalls, ...novelReasoningCalls];
for (const c of calls) turnExecuted.add(key(c));

const visible = stripToolBlocks(res.content);
// Text alongside reasoning-only calls is a premature conclusion — hold it.
const prematureText = contentCalls.length === 0 && novelReasoningCalls.length > 0;
if (visible && !prematureText) cb.onAssistantText?.(visible);
trace("turn.assistant", { round, chars: res.content.length, tool_calls: calls.length });

state.messages.push({ role: "assistant", content: res.content });

if (calls.length === 0) {
  if (visible && prematureText) cb.onAssistantText?.(visible);
  logger.info("turn.done", { rounds: round + 1 });
  return;
